// Bollard UI — transit-visa-check · MIT licence · https://bollard-ui.vercel.app/components/transit-visa-check

/** Transit visa rules and the pure check. Countries are ISO 3166-1 alpha-2 codes ("IN", "GB"). */

/** Documents that commonly exempt a traveller from an airport transit visa. */
export type TransitDocument = "us-visa" | "us-residence" | "ca-visa" | "ca-residence" | "au-visa" | "nz-visa" | "uk-visa" | "uk-residence" | "schengen-visa" | "eea-residence" | "jp-visa"

export interface TransitRule {
  /** Country name for display. */
  country: string
  /** ISO alpha-2 of the country. Its own citizens never need a visa. */
  code: string
  /** "schengen": the next flight to another Schengen country means entering here. */
  zone?: "schengen"
  /** Nationalities who can always pass the border (EU/EEA/Swiss in Schengen, Irish in the UK). */
  freeMovement?: string[]
  /** No airside transit at all: every passenger clears immigration (the United States). */
  noAirside?: boolean
  /** Nationalities that need a visa even to stay airside. */
  airsideVisa: string[]
  /** Nationalities that need it only in some cases, with the condition in words. Gives "check". */
  airsideVisaIf?: Record<string, string>
  /** Name of that visa. */
  airsideVisaName: string
  /** Documents that exempt those nationalities from the airside visa. Conditions apply; `exemptionNote` says which. */
  exemptWith?: TransitDocument[]
  exemptionNote?: string
  /** What passing the border needs, in words. */
  entryNote: string
  /** Nationalities that need a visa to enter (pass the border), if you have the list. Without it, entering is "check". */
  entryVisa?: string[]
  /** Documents that let a visa national pass the border here (a Schengen visa in Schengen). Gives "clear". */
  entryExemptWith?: TransitDocument[]
  /** Documents that may let a visa national pass the border for a short landside transit, with conditions. Gives "check". */
  landsideTransitWith?: TransitDocument[]
  landsideTransitNote?: string
  /** Onward countries that force a landside transit (the UK for Ireland). */
  landsideOnward?: string[]
  /** Whether a terminal change keeps you airside: true = always landside, false = always airside, undefined = it depends. */
  terminalChangeLandside?: boolean
  /** Hours you can wait airside, if limited. */
  maxAirsideHours?: number
  /** Official page the rule comes from, and when it was checked (YYYY-MM-DD). */
  source: string
  checked: string
}

/** The 29 Schengen states (Bulgaria and Romania fully since 1 Jan 2025). */
export const SCHENGEN = ["AT", "BE", "BG", "HR", "CZ", "DK", "EE", "FI", "FR", "DE", "GR", "HU", "IS", "IT", "LV", "LI", "LT", "LU", "MT", "NL", "NO", "PL", "PT", "RO", "SK", "SI", "ES", "SE", "CH"]
/** EU/EEA/Swiss citizens move freely in Schengen: Schengen states plus the EU members outside it. */
const FREE_IN_SCHENGEN = [...SCHENGEN, "IE", "CY"]

const UK: TransitRule = {
  country: "United Kingdom",
  code: "GB",
  freeMovement: ["IE"],
  // The Immigration (Passenger Transit Visa) Order 2014, Schedule 1, as amended to 6 Mar 2026 (70 nationalities).
  airsideVisa: ["AF", "AL", "DZ", "AO", "BD", "BY", "BW", "MM", "BI", "CM", "CO", "CG", "CD", "DM", "EG", "SV", "ER", "ET", "MK", "GM", "GE", "GH", "GN", "GW", "HN", "IN", "IR", "IQ", "CI", "JM", "JO", "KE", "XK", "LB", "LS", "LR", "LY", "MW", "MD", "MN", "NA", "NR", "NP", "NI", "NG", "PK", "PS", "CN", "RU", "RW", "SN", "RS", "SL", "SO", "ZA", "SS", "LK", "LC", "SD", "SZ", "SY", "TZ", "TL", "TT", "TR", "UG", "VU", "VN", "YE", "ZW"],
  airsideVisaName: "Direct Airside Transit Visa (DATV)",
  // Article 4: valid AU/CA/NZ/US visa (or one used to enter within 6 months), their permanent residence, an EEA/Swiss
  // residence permit; gov.uk: a UK Standard Visitor visa also does.
  exemptWith: ["uk-visa", "us-visa", "us-residence", "ca-visa", "ca-residence", "au-visa", "nz-visa", "eea-residence"],
  exemptionNote: "Paper documents only, unless the airline can verify an e-visa. Syrians with a US B1/B2 visa still need a DATV.",
  entryNote: "Passing UK border control needs a Visitor in Transit visa (leave within 48 hours) for visa nationals, or an ETA for most others.",
  landsideTransitWith: ["us-visa", "us-residence", "ca-visa", "ca-residence", "au-visa", "nz-visa", "eea-residence"],
  landsideTransitNote: "With it you may get Transit Without Visa at the border if you leave by 23:59 the next day. Conditions apply, so check before you rely on it.",
  landsideOnward: ["IE"],
  source: "https://www.legislation.gov.uk/uksi/2014/2702/article/4",
  checked: "2026-10-14",
}
/** Regulation (EC) 810/2009 Art. 3(5): exemptions every Schengen state applies. */
const SCHENGEN_EXEMPT: TransitDocument[] = ["schengen-visa", "eea-residence", "us-visa", "us-residence", "ca-visa", "ca-residence", "jp-visa"]
const SCHENGEN_ENTRY = {
  entryNote: "Leaving the transit area means entering Schengen: you need a Schengen visa unless your passport is visa-free (then an ETIAS once it starts).",
  entryExemptWith: ["schengen-visa", "eea-residence"] as TransitDocument[],
}
const DE: TransitRule = {
  country: "Germany",
  code: "DE",
  zone: "schengen",
  freeMovement: FREE_IN_SCHENGEN,
  // Federal Foreign Office list, June 2026 (India removed 3 June 2026).
  airsideVisa: ["AF", "BD", "ML", "SD", "ET", "GH", "LK", "ER", "JO", "LB", "CD", "IQ", "SO", "SS", "IR", "PK", "TR", "CU", "NG", "SY"],
  airsideVisaName: "airport transit visa (Schengen type A)",
  exemptWith: SCHENGEN_EXEMPT,
  exemptionNote: "Germany lists the exact permits that count; an I-797 or advance parole does not. Jordanians flying to or from Australia, Israel or New Zealand on that country's visa are exempt for up to 12 hours.",
  ...SCHENGEN_ENTRY,
  source: "https://www.germany.info/us-en/service/visa/airport-transit-visa-924624",
  checked: "2026-10-14",
}
const FR: TransitRule = {
  country: "France",
  code: "FR",
  zone: "schengen",
  freeMovement: FREE_IN_SCHENGEN,
  // France-Visas, airport transit visa page (India removed 10 April 2026). National additions apply to ordinary passports.
  airsideVisa: ["AF", "BD", "CD", "ER", "ET", "GH", "IR", "IQ", "NG", "PK", "SO", "LK", "AO", "BO", "CM", "CF", "TD", "CI", "CU", "DO", "HT", "ML", "MR", "NP", "PH", "GN", "CG", "SN", "SL", "SS", "SD", "SY", "TG", "TR", "UZ"],
  airsideVisaIf: { RU: "Russians need it only when flying in from Armenia, Azerbaijan, Georgia, Ukraine, Belarus, Moldova, Turkey or Egypt." },
  airsideVisaName: "airport transit visa (Schengen type A)",
  exemptWith: [...SCHENGEN_EXEMPT, "uk-residence"],
  exemptionNote: "Residence permits must guarantee your return. Diplomatic passports and Philippine seafarers are exempt too.",
  ...SCHENGEN_ENTRY,
  source: "https://france-visas.gouv.fr/en/web/france-visas/visa-de-transit-aeroportuaire",
  checked: "2026-10-14",
}
const NL: TransitRule = {
  country: "Netherlands",
  code: "NL",
  zone: "schengen",
  freeMovement: FREE_IN_SCHENGEN,
  // EU common list (Reg. 810/2009 Annex IV) plus the Dutch additions in the Dutch AIP GEN 1.3 (AIRAC 07-2026).
  airsideVisa: ["AF", "BD", "CD", "ER", "ET", "GH", "IR", "IQ", "NG", "PK", "SO", "LK", "AO", "IN", "LB", "SY", "TR"],
  airsideVisaName: "airport transit visa (Schengen type A)",
  exemptWith: SCHENGEN_EXEMPT,
  exemptionNote: "Lawful residence in the EU, Canada, Norway, Switzerland or the US also counts.",
  ...SCHENGEN_ENTRY,
  source: "https://eaip.lvnl.nl/web/eaip/AIRAC%20AMDT%2007-2026_2026_07_09/eAIP/EH-GEN%201.3-en-GB.html",
  checked: "2026-10-14",
}
const US: TransitRule = {
  country: "United States",
  code: "US",
  noAirside: true,
  airsideVisa: [],
  airsideVisaName: "transit (C-1) visa",
  entryNote: "Even to change planes you need an ESTA (Visa Waiver countries) or a US visa such as B or C-1.",
  source: "https://travel.state.gov/content/travel/en/us-visas/other-visa-categories/transit.html",
  checked: "2026-10-14",
}

/** Starter rules by airport (IATA). Small on purpose: replace or extend them from Timatic or the official source. */
export const TRANSIT_RULES: Record<string, TransitRule & { airport: string; hours?: string }> = {
  LHR: { ...UK, airport: "London Heathrow" },
  LGW: { ...UK, airport: "London Gatwick" },
  MAN: { ...UK, airport: "Manchester" },
  FRA: { ...DE, airport: "Frankfurt" },
  MUC: { ...DE, airport: "Munich" },
  BER: { ...DE, airport: "Berlin Brandenburg" },
  DUS: { ...DE, airport: "Düsseldorf", hours: "06:00–21:00" },
  HAM: { ...DE, airport: "Hamburg", hours: "04:30–23:30" },
  CDG: { ...FR, airport: "Paris Charles de Gaulle" },
  ORY: { ...FR, airport: "Paris Orly" },
  AMS: { ...NL, airport: "Amsterdam Schiphol" },
  JFK: { ...US, airport: "New York JFK" },
  EWR: { ...US, airport: "Newark" },
  SFO: { ...US, airport: "San Francisco" },
  LAX: { ...US, airport: "Los Angeles" },
}

export interface Layover {
  /** Passport nationality, ISO alpha-2. */
  nationality: string
  /** Airport, IATA code (a key in the rules). */
  airport: string
  /** Where the next flight goes, ISO alpha-2. */
  onward?: string
  /** Planning to leave the airport during the layover. */
  landside?: boolean
  /** Booked as a self-transfer (you rebook and re-check bags yourself). */
  selfTransfer?: boolean
  /** The two flights are on separate tickets. */
  separateTickets?: boolean
  /** The connection changes terminals. */
  terminalChange?: boolean
  /** Layover length in hours. */
  hours?: number
  /** Visas and permits the traveller holds. */
  documents?: TransitDocument[]
}

export type TransitReason =
  | { kind: "citizen" }
  | { kind: "freeMovement" }
  | { kind: "noAirside" }
  | { kind: "selfTransfer" }
  | { kind: "separateTickets" }
  | { kind: "terminal"; certain: boolean }
  | { kind: "leaving" }
  | { kind: "tooLong"; max: number }
  | { kind: "onwardZone"; onward: string }
  | { kind: "onwardLandside"; onward: string }
  | { kind: "airsideVisa"; name: string }
  | { kind: "exempt"; documents: TransitDocument[]; note?: string }
  | { kind: "conditional"; note: string }
  | { kind: "entryExempt"; documents: TransitDocument[] }
  | { kind: "landsideTransit"; documents: TransitDocument[]; note?: string }
  | { kind: "airsideClear" }
  | { kind: "entry"; note: string }
  | { kind: "hours"; hours: string }

export interface TransitCheck {
  /** "visa": a visa is very likely needed; "check": it depends on something only an official source can settle; "clear": no visa listed. */
  verdict: "visa" | "check" | "clear" | "unknown"
  /** True when the plan means passing the border. */
  entering: boolean
  reasons: TransitReason[]
  rule?: TransitRule
}

const code = (s: unknown) => String(s ?? "").trim().toUpperCase().slice(0, 3)

/** Says whether a layover may need a transit or entry visa, and why. Never throws. */
export function checkTransit(layover: Partial<Layover> | null | undefined, rules: Record<string, TransitRule & { hours?: string }> = TRANSIT_RULES): TransitCheck {
  const l = layover ?? {}
  const rule = rules?.[code(l.airport)]
  const nat = code(l.nationality)
  if (!rule || !nat) return { verdict: "unknown", entering: false, reasons: [] }
  if (nat === rule.code) return { verdict: "clear", entering: true, reasons: [{ kind: "citizen" }], rule }
  if (rule.freeMovement?.includes(nat)) return { verdict: "clear", entering: true, reasons: [{ kind: "freeMovement" }], rule }

  const reasons: TransitReason[] = []
  let certain = false
  let maybe = false
  const onward = code(l.onward)
  if (rule.noAirside) { reasons.push({ kind: "noAirside" }); certain = true }
  if (l.selfTransfer) { reasons.push({ kind: "selfTransfer" }); certain = true }
  // Separate tickets without checked bags can stay airside at some hubs, so this is "check", not certain.
  if (l.separateTickets && !l.selfTransfer) { reasons.push({ kind: "separateTickets" }); maybe = true }
  if (l.landside) { reasons.push({ kind: "leaving" }); certain = true }
  if (onward && rule.zone === "schengen" && SCHENGEN.includes(onward)) { reasons.push({ kind: "onwardZone", onward }); certain = true }
  if (onward && rule.landsideOnward?.includes(onward)) { reasons.push({ kind: "onwardLandside", onward }); certain = true }
  if (l.terminalChange && rule.terminalChangeLandside !== false) {
    reasons.push({ kind: "terminal", certain: rule.terminalChangeLandside === true })
    if (rule.terminalChangeLandside) certain = true
    else maybe = true
  }
  const hours = Number(l.hours)
  if (rule.maxAirsideHours && Number.isFinite(hours) && hours > rule.maxAirsideHours) { reasons.push({ kind: "tooLong", max: rule.maxAirsideHours }); certain = true }

  const held = Array.isArray(l.documents) ? l.documents : []
  const among = (list?: TransitDocument[]) => held.filter((d) => list?.includes(d))
  const docs = among(rule.exemptWith)
  const listed = rule.airsideVisa.includes(nat)
  const condition = rule.airsideVisaIf?.[nat]
  if (certain) {
    reasons.push({ kind: "entry", note: rule.entryNote })
    const entryDocs = among(rule.entryExemptWith)
    if (entryDocs.length) {
      reasons.push({ kind: "entryExempt", documents: entryDocs })
      return { verdict: "clear", entering: true, reasons, rule }
    }
    const needsVisa = listed || !!condition || !!rule.entryVisa?.includes(nat)
    const landDocs = among(rule.landsideTransitWith)
    if (needsVisa && landDocs.length) {
      reasons.push({ kind: "landsideTransit", documents: landDocs, note: rule.landsideTransitNote })
      return { verdict: "check", entering: true, reasons, rule }
    }
    return { verdict: needsVisa ? "visa" : "check", entering: true, reasons, rule }
  }
  if ((listed || condition) && docs.length) reasons.push({ kind: "exempt", documents: docs, note: rule.exemptionNote })
  else if (listed) reasons.push({ kind: "airsideVisa", name: rule.airsideVisaName })
  else if (condition) reasons.push({ kind: "conditional", note: condition })
  else reasons.push({ kind: "airsideClear" })
  if (rule.hours) reasons.push({ kind: "hours", hours: rule.hours })
  if (maybe) reasons.push({ kind: "entry", note: rule.entryNote })
  const verdict = listed && !docs.length ? "visa" : listed || condition || maybe ? "check" : "clear"
  return { verdict, entering: false, reasons, rule }
}

"use client"

// Bollard UI — transit-visa-check · MIT licence · https://bollard-ui.vercel.app/components/transit-visa-check

import * as React from "react"
import { CircleCheck, CircleHelp, CircleX, ExternalLink, Luggage, PlaneLanding, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkTransit, SCHENGEN, TRANSIT_RULES, type Layover, type TransitDocument, type TransitReason, type TransitRule } from "./transit-rules"

export { checkTransit, SCHENGEN, TRANSIT_RULES, type Layover, type TransitCheck, type TransitDocument, type TransitReason, type TransitRule } from "./transit-rules"

/** Every visible string. `{…}` placeholders are filled in. */
export const TRANSIT_VISA_MESSAGES = {
  heading: "Transit check",
  nationality: "Passport",
  airport: "Layover at",
  onward: "Flying on to",
  elsewhere: "Somewhere else",
  hours: "Layover (hours)",
  plan: "How you connect",
  selfTransfer: "Self-transfer",
  separateTickets: "Separate tickets",
  terminalChange: "Change terminals",
  landside: "Leave the airport",
  documents: "Visas or permits you hold",
  docs: {
    "us-visa": "US visa", "us-residence": "US green card", "ca-visa": "Canada visa", "ca-residence": "Canada PR",
    "au-visa": "Australia visa", "nz-visa": "New Zealand visa", "uk-visa": "UK visa", "schengen-visa": "Schengen visa",
    "eea-residence": "EU/EEA residence permit", "jp-visa": "Japan visa", "uk-residence": "UK residence permit",
  } as Record<TransitDocument, string>,
  verdict: { visa: "You'll likely need a visa for this layover", check: "Check before you book", clear: "No transit visa listed for this layover", unknown: "Pick your passport and layover airport" },
  citizen: "You're a citizen here: no visa needed.",
  freeMovement: "Your passport lets you pass the border in {country}: no visa needed.",
  noAirside: "{country} has no airside transit: everyone clears immigration, even to change planes.",
  selfTransferWhy: "Self-transfer means collecting your bags and checking in again, so you have to enter {country}.",
  separateTicketsWhy: "On separate tickets the airline usually won't check bags through, so you'll likely enter {country} to re-check them.",
  terminalMaybe: "Some terminal changes go through immigration. Check that yours stays airside.",
  terminalCertain: "This terminal change goes through immigration, so you enter {country}.",
  leaving: "Leaving the airport means entering {country}.",
  tooLong: "Airside waits here are limited to {max} hours.",
  onwardZone: "Your next flight is to {onward}, inside Schengen, so you enter Schengen here in {country}.",
  onwardLandside: "Flights to {onward} leave from the landside, so you enter {country}.",
  airsideVisa: "{nationality} passports need a {visa} even to stay airside in {country}.",
  exempt: "Your {documents} usually exempts you from the {visa}. {note}",
  conditional: "{note} Otherwise no {visa} is needed.",
  entryExempt: "Your {documents} lets you pass the border here, if it's valid for these dates (a residence permit must be from a Schengen state).",
  landsideTransit: "You hold a {documents}. {note}",
  airsideClear: "{nationality} passports aren't on {country}'s airport transit visa list, if you stay airside.",
  hoursNote: "Airside transit here only runs {hours}.",
  verify: "Rules change and airlines can be stricter. Rules checked {date}: verify with Timatic or the official source.",
  official: "Official source",
  timatic: "Timatic (IATA)",
}
export type TransitVisaMessages = typeof TRANSIT_VISA_MESSAGES

const fill = (s: string, v: Record<string, string | number | undefined>) => s.replace(/\{(\w+)\}/g, (m, k: string) => String(v[k] ?? m))
const field = "h-9 w-full min-w-0 rounded-md border bg-transparent px-3 text-base shadow-xs outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 md:text-sm dark:bg-input/30 [&>option]:bg-popover"
const TIMATIC = "https://www.iatatravelcentre.com/"
const COMMON = ["IN", "US", "GB", "CA", "AU", "NZ", "AE", "SG", "JP", "IE", "BR", "MX", "ZA"]
const TONES = { visa: "border-red-500/40 bg-red-500/5 text-red-700 dark:text-red-400", check: "border-amber-500/40 bg-amber-500/5 text-amber-800 dark:text-amber-300", clear: "border-emerald-500/40 bg-emerald-500/5 text-emerald-700 dark:text-emerald-400", unknown: "text-muted-foreground" }
const ICONS = { visa: CircleX, check: TriangleAlert, clear: CircleCheck, unknown: CircleHelp }

export interface TransitVisaCheckProps extends Omit<React.ComponentProps<"section">, "defaultValue" | "onChange"> {
  /** Controlled layover. */
  value?: Partial<Layover>
  /** Initial layover when uncontrolled. */
  defaultValue?: Partial<Layover>
  /** Called on every change. */
  onValueChange?: (value: Partial<Layover>) => void
  /** Rules by airport IATA code. Defaults to a small, sourced starter set; replace with your own data. */
  rules?: Record<string, TransitRule & { airport?: string; hours?: string }>
  /** Countries offered for passport and onward flight, ISO alpha-2. Defaults to every country the rules mention. */
  countries?: string[]
  /** Locale for country names and dates. */
  locale?: string
  /** Pause in ms before the verdict is read out after a change. */
  delay?: number
  /** Any visible string; `verdict` and `docs` may be partial. */
  messages?: Partial<Omit<TransitVisaMessages, "verdict" | "docs">> & { verdict?: Partial<TransitVisaMessages["verdict"]>; docs?: Partial<TransitVisaMessages["docs"]> }
}

/**
 * Flags a layover that may need a transit or entry visa before the ticket is bought: nationalities on an airport
 * transit visa list, airports with no airside transit, and the traps people miss — self-transfer and separate
 * tickets (you must enter to re-check bags), terminal changes, an onward flight inside Schengen and leaving the
 * airport. Rules come from props, with a small sourced default set and a link to verify.
 */
export function TransitVisaCheck({
  value, defaultValue = {}, onValueChange, rules = TRANSIT_RULES, countries, locale = "en-IN", delay = 700, messages, className, ...props
}: TransitVisaCheckProps) {
  const t = { ...TRANSIT_VISA_MESSAGES, ...messages, verdict: { ...TRANSIT_VISA_MESSAGES.verdict, ...messages?.verdict }, docs: { ...TRANSIT_VISA_MESSAGES.docs, ...messages?.docs } }
  const [inner, setInner] = React.useState<Partial<Layover>>(defaultValue)
  const layover = value ?? inner
  const result = checkTransit(layover, rules)
  const rule = result.rule
  const [status, setStatus] = React.useState("")
  const id = React.useId()

  const names = React.useMemo(() => {
    try { return new Intl.DisplayNames([locale], { type: "region" }) } catch { return null }
  }, [locale])
  const name = (c?: string) => (c ? (names?.of(c) ?? c) : "")
  const list = React.useMemo(() => {
    const all = countries ?? [...new Set([...COMMON, ...SCHENGEN, ...Object.values(rules ?? {}).flatMap((r) => [r.code, ...r.airsideVisa])])]
    return all.filter((c) => /^[A-Z]{2}$/.test(c)).map((c) => [c, names?.of(c) ?? c] as const).sort((a, b) => a[1].localeCompare(b[1], locale))
  }, [countries, rules, names, locale])

  const commit = (patch: Partial<Layover>) => {
    const next = { ...layover, ...patch }
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }

  const docsText = (docs: TransitDocument[]) => (typeof Intl.ListFormat === "function" ? new Intl.ListFormat(locale, { type: "disjunction" }).format(docs.map((d) => t.docs[d] ?? d)) : docs.map((d) => t.docs[d] ?? d).join(", "))
  const text = (r: TransitReason) => {
    const v = { country: rule?.country, nationality: name(layover.nationality), visa: rule?.airsideVisaName }
    switch (r.kind) {
      case "citizen": return t.citizen
      case "freeMovement": return fill(t.freeMovement, v)
      case "conditional": return fill(t.conditional, { ...v, note: r.note })
      case "entryExempt": return fill(t.entryExempt, { documents: docsText(r.documents) })
      case "landsideTransit": return fill(t.landsideTransit, { documents: docsText(r.documents), note: r.note ?? "" }).trim()
      case "noAirside": return fill(t.noAirside, v)
      case "selfTransfer": return fill(t.selfTransferWhy, v)
      case "separateTickets": return fill(t.separateTicketsWhy, v)
      case "terminal": return fill(r.certain ? t.terminalCertain : t.terminalMaybe, v)
      case "leaving": return fill(t.leaving, v)
      case "tooLong": return fill(t.tooLong, { max: r.max })
      case "onwardZone": return fill(t.onwardZone, { ...v, onward: name(r.onward) })
      case "onwardLandside": return fill(t.onwardLandside, { ...v, onward: name(r.onward) })
      case "airsideVisa": return fill(t.airsideVisa, v)
      case "exempt": return fill(t.exempt, { ...v, documents: docsText(r.documents), note: r.note ?? "" }).trim()
      case "airsideClear": return fill(t.airsideClear, v)
      case "entry": return r.note
      case "hours": return fill(t.hoursNote, { hours: r.hours })
    }
  }
  const verdict = t.verdict[result.verdict]
  const spoken = [verdict, ...result.reasons.map(text)].join(" ")
  React.useEffect(() => {
    const timer = setTimeout(() => setStatus(spoken), delay)
    return () => clearTimeout(timer)
  }, [spoken, delay])

  const toggle = (key: "selfTransfer" | "separateTickets" | "terminalChange" | "landside", label: string) => (
    <label className="inline-flex h-8 cursor-pointer items-center gap-2 rounded-md border px-3 text-xs font-medium transition-colors has-[:checked]:border-primary/50 has-[:checked]:bg-accent has-[:focus-visible]:ring-[3px] has-[:focus-visible]:ring-ring/50">
      <input type="checkbox" checked={!!layover[key]} onChange={(e) => commit({ [key]: e.target.checked })} className="size-3.5 accent-primary outline-none" />
      {label}
    </label>
  )
  // Offer the documents that can change the answer: airside exemptions for listed passports, and the entry or
  // landside-transit documents once the plan means passing the border.
  const nat = String(layover.nationality ?? "").toUpperCase()
  const free = !rule || nat === rule.code || !!rule.freeMovement?.includes(nat)
  const needsAirside = !!rule && (rule.airsideVisa.includes(nat) || !!rule.airsideVisaIf?.[nat])
  const exemptDocs = free ? [] : [...new Set([
    ...(needsAirside && !result.entering ? rule?.exemptWith ?? [] : []),
    ...(result.entering ? [...(rule?.entryExemptWith ?? []), ...(needsAirside ? rule?.landsideTransitWith ?? [] : [])] : []),
  ])]
  const Icon = ICONS[result.verdict]

  return (
    <section aria-labelledby={`${id}-h`} data-slot="transit-visa-check" data-state={result.verdict}
      className={cn("@container grid w-full max-w-md min-w-0 gap-3 rounded-lg border bg-card p-4 text-sm text-card-foreground shadow-xs", className)} {...props}>
      <h3 id={`${id}-h`} className="flex items-center gap-2 font-medium">
        <PlaneLanding aria-hidden className="size-4 shrink-0 text-muted-foreground" />
        {t.heading}
      </h3>

      <div className="grid min-w-0 gap-3 @sm:grid-cols-2">
        <div className="grid min-w-0 gap-1.5">
          <label htmlFor={`${id}-nat`} className="text-xs font-medium">{t.nationality}</label>
          <select id={`${id}-nat`} value={layover.nationality ?? ""} onChange={(e) => commit({ nationality: e.target.value })} className={field}>
            <option value="" disabled>—</option>
            {list.map(([c, n]) => <option key={c} value={c}>{n}</option>)}
          </select>
        </div>
        <div className="grid min-w-0 gap-1.5">
          <label htmlFor={`${id}-apt`} className="text-xs font-medium">{t.airport}</label>
          <select id={`${id}-apt`} value={layover.airport ?? ""} onChange={(e) => commit({ airport: e.target.value })} className={field}>
            <option value="" disabled>—</option>
            {Object.entries(rules ?? {}).map(([iata, r]) => <option key={iata} value={iata}>{iata} · {r.airport ?? r.country}</option>)}
          </select>
        </div>
        <div className="grid min-w-0 gap-1.5">
          <label htmlFor={`${id}-on`} className="text-xs font-medium">{t.onward}</label>
          <select id={`${id}-on`} value={layover.onward ?? ""} onChange={(e) => commit({ onward: e.target.value })} className={field}>
            <option value="">{t.elsewhere}</option>
            {list.map(([c, n]) => <option key={c} value={c}>{n}</option>)}
          </select>
        </div>
        <div className="grid min-w-0 gap-1.5">
          <label htmlFor={`${id}-hrs`} className="text-xs font-medium">{t.hours}</label>
          <input id={`${id}-hrs`} type="number" inputMode="decimal" min={0} max={240} value={layover.hours ?? ""}
            onChange={(e) => commit({ hours: e.target.value === "" ? undefined : Math.max(0, Math.min(240, Number(e.target.value) || 0)) })} className={field} />
        </div>
      </div>

      <fieldset className="grid gap-1.5">
        <legend className="mb-1.5 text-xs font-medium">{t.plan}</legend>
        <div className="flex flex-wrap gap-1.5">
          {toggle("selfTransfer", t.selfTransfer)}
          {toggle("separateTickets", t.separateTickets)}
          {toggle("terminalChange", t.terminalChange)}
          {toggle("landside", t.landside)}
        </div>
      </fieldset>

      {exemptDocs.length > 0 && (
        <fieldset className="grid gap-1.5">
          <legend className="mb-1.5 text-xs font-medium">{t.documents}</legend>
          <div className="flex flex-wrap gap-1.5">
            {exemptDocs.map((d) => (
              <label key={d} className="inline-flex h-8 cursor-pointer items-center gap-2 rounded-md border px-3 text-xs transition-colors has-[:checked]:bg-accent has-[:focus-visible]:ring-[3px] has-[:focus-visible]:ring-ring/50">
                <input type="checkbox" checked={!!layover.documents?.includes(d)} className="size-3.5 accent-primary outline-none"
                  onChange={(e) => commit({ documents: e.target.checked ? [...(layover.documents ?? []), d] : (layover.documents ?? []).filter((x) => x !== d) })} />
                {t.docs[d] ?? d}
              </label>
            ))}
          </div>
        </fieldset>
      )}

      <div className={cn("grid gap-2 rounded-md border px-3 py-2", TONES[result.verdict])}>
        <p className="flex items-center gap-1.5 font-medium">
          <Icon aria-hidden className="size-4 shrink-0" />
          {verdict}
        </p>
        {result.reasons.length > 0 && (
          <ul className="grid gap-1.5 text-xs text-foreground">
            {result.reasons.map((r, i) => (
              <li key={`${r.kind}-${i}`} className="flex gap-1.5">
                {r.kind === "selfTransfer" || r.kind === "separateTickets" ? <Luggage aria-hidden className="mt-0.5 size-3.5 shrink-0 text-muted-foreground" /> : <span aria-hidden className="mt-1.5 size-1.5 shrink-0 rounded-full bg-current opacity-50" />}
                <span className="min-w-0 break-words">{text(r)}</span>
              </li>
            ))}
          </ul>
        )}
      </div>

      <p className="border-t pt-3 text-xs text-muted-foreground">
        {fill(t.verify, { date: rule?.checked ? new Intl.DateTimeFormat(locale, { timeZone: "UTC", day: "numeric", month: "short", year: "numeric" }).format(Date.parse(rule.checked) || 0) : "—" })}{" "}
        <span className="inline-flex flex-wrap gap-x-3">
          {rule?.source && (
            <a href={rule.source} target="_blank" rel="noreferrer noopener" className="inline-flex items-center gap-1 rounded-sm font-medium text-foreground underline underline-offset-2 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
              {t.official}<ExternalLink aria-hidden className="size-3" />
            </a>
          )}
          <a href={TIMATIC} target="_blank" rel="noreferrer noopener" className="inline-flex items-center gap-1 rounded-sm font-medium text-foreground underline underline-offset-2 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
            {t.timatic}<ExternalLink aria-hidden className="size-3" />
          </a>
        </span>
      </p>
      <span aria-live="polite" className="sr-only">{status}</span>
    </section>
  )
}
